/** Explicit review enforcement on a `.agentic-owners` policy rule. */
export type AgenticOwnersPolicyMode = "hard" | "advisory" | "notify";

const POLICY_MODES: readonly AgenticOwnersPolicyMode[] = ["hard", "advisory", "notify"];

export function parseAgenticOwnersPolicyMode(
  value: unknown,
  label: string,
  issues: string[],
): AgenticOwnersPolicyMode | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== "string") {
    issues.push(`${label}: mode must be hard, advisory, or notify`);
    return undefined;
  }
  const normalized = value.trim().toLowerCase();
  if (!isPolicyMode(normalized)) {
    issues.push(`${label}: mode must be hard, advisory, or notify`);
    return undefined;
  }
  return normalized;
}

function isPolicyMode(value: string): value is AgenticOwnersPolicyMode {
  return POLICY_MODES.some((mode) => mode === value);
}

export function resolvePolicyModeFromFields(args: {
  mode: AgenticOwnersPolicyMode | undefined;
  humanReviewRequired: boolean;
  label: string;
  issues: string[];
}): AgenticOwnersPolicyMode | undefined {
  const { mode, humanReviewRequired, label, issues } = args;
  if (mode === undefined) {
    return humanReviewRequired ? "hard" : "advisory";
  }
  if (humanReviewRequired && mode !== "hard") {
    issues.push(`${label}: human_review_required: true requires mode: hard (or omit mode)`);
  }
  return mode;
}

export function ruleIsHardGate(rule: {
  readonly mode?: AgenticOwnersPolicyMode;
  readonly humanReviewRequired: boolean;
}): boolean {
  if (rule.mode === "notify") {
    return false;
  }
  if (rule.mode === "hard") {
    return true;
  }
  return rule.humanReviewRequired;
}

export function ruleIsNotifyOnly(rule: { readonly mode?: AgenticOwnersPolicyMode }): boolean {
  return rule.mode === "notify";
}
